# Check if sex is valid
   if sex not in ['M', 'F']:
       raise ValueError("sex must be 'M' or 'F'")

   # Initialize score
   score = 0

   # Congestive heart failure
   if chf:
       score += 1

   # Hypertension
   if hypertension:
       score += 1

   # Age >= 75 years
   if age >= 75:
       score += 2

   # Diabetes mellitus
   if diabetes:
       score += 1

   # Prior stroke, TIA or thromboembolism
   if stroke_tia:
       score += 2

   # Vascular disease
   if vascular:
       score += 1

   # Age 65-74 years
   if 65 <= age < 75:
       score += 1

   # Female sex
   if sex == 'F':
       score += 1

   return score

# Initialize the score to 0
   score = 0

   # Uncontrolled hypertension
   if hypertension:
       score += 1

   # Abnormal renal function
   if abnormal_renal:
       score += 1

   # Abnormal liver function
   if abnormal_liver:
       score += 1

   # Prior stroke
   if stroke:
       score += 1

   # Bleeding history or predisposition
   if bleeding:
       score += 1

   # Labile INR
   if labile_inr:
       score += 1

   # Elderly (age > 65 years)
   if age > 65:
       score += 1

   # Concomitant antiplatelet or NSAID drugs
   if drugs:
       score += 1

   # Alcohol use (>= 8 drinks per week)
   if alcohol:
       score += 1

   return score

# Check if age is within valid range
   if age < 3:
       raise ValueError("Age must be 3 or older")

   # Initialize score to 0
   score = 0

   # Add points for each condition
   if exudate_or_swelling:
       score += 1
   if tender_anterior_nodes:
       score += 1
   if fever_history:
       score += 1
   if cough_absent:
       score += 1

   # Apply age adjustment
   if 3 <= age <= 14:
       score += 1
   elif 15 <= age <= 44:
       pass
   else:
       score -= 1

   return score

# Check if points are within the valid range
   if not 5 <= points <= 15:
       raise ValueError("Child-Pugh score must be between 5 and 15")

   # Determine the Child-Pugh class based on the points
   if points <= 6:
       return 'A'
   elif points <= 9:
       return 'B'
   else:
       return 'C'

# Check if FiO2 is non-positive and raise ValueError if true
   if fio2 <= 0:
       raise ValueError("FiO2 must be greater than zero.")

   # Calculate the PaO2/FiO2 ratio
   ratio = pao2 / fio2

   # Classify the oxygenation based on the ratio
   if ratio > 300:
       return 'none'
   elif 200 <= ratio <= 300:
       return 'mild'
   elif 100 < ratio <= 200:
       return 'moderate'
   else:
       return 'severe'

# Check for 'crisis' category
   if sbp > 180 or dbp > 120:
       return 'crisis'

   # Check for 'stage 2' category
   elif sbp >= 140 or dbp >= 90:
       return 'stage 2'

   # Check for 'stage 1' category
   elif 130 <= sbp <= 139 and 80 <= dbp <= 89:
       return 'stage 1'

   # Check for 'elevated' category
   elif 120 <= sbp <= 129 and dbp < 80:
       return 'elevated'

   # If none of the above conditions are met, return 'normal'
   else:
       return 'normal'

# Check if weight is negative and raise ValueError if true
   if weight_kg < 0:
       raise ValueError("Weight cannot be negative.")

   # Calculate the maintenance fluid rate
   if weight_kg <= 10:
       return round(4 * weight_kg, 1)
   elif weight_kg <= 20:
       return round(4 * 10 + 2 * (weight_kg - 10), 1)
   else:
       return round(4 * 10 + 2 * 10 + (weight_kg - 20) * 1, 1)

# Convert height from cm to m
   height_m = height_cm / 100

   # Calculate the resting energy expenditure
   if sex.upper() == 'M':
       return round(10 * weight_kg + 6.25 * height_m - 5 * age + 5)
   elif sex.upper() == 'F':
       return round(10 * weight_kg + 6.25 * height_m - 5 * age - 161)
   else:
       raise ValueError("Invalid sex value. Please use 'M' for men or 'F' for women.")

# Check if albumin is non-positive and raise ValueError if true
   if albumin_g_dl <= 0:
       raise ValueError("Albumin cannot be non-positive.")

   # Apply the Sheiner-Tozer equation for non-end-stage renal disease
   if not end_stage_renal:
       return round(measured_mg_l / (0.2 * albumin_g_dl + 0.1), 1)

   # Apply the Sheiner-Tozer equation for end-stage renal disease
   else:
       return round(measured_mg_l / (0.1 * albumin_g_dl + 0.1), 1)

# Check if the sequence is shorter than k
   if len(seq) < k:
       return {}

   # Initialize an empty dictionary to store the k-mer counts
   kmer_dict = {}

   # Iterate over the sequence with a sliding window of size k
   for i in range(len(seq) - k + 1):
       # Extract the current k-mer
       kmer = seq[i:i+k]

       # Check if the k-mer contains 'N'
       if 'N' not in kmer:
           # If the k-mer is already in the dictionary, increment its count
           if kmer in kmer_dict:
               kmer_dict[kmer] += 1
           # Otherwise, add the k-mer to the dictionary with a count of 1
           else:
               kmer_dict[kmer] = 1

   # Return the dictionary of k-mer counts
   return kmer_dict

# Check if the input list is empty
   if not genotypes:
       return 0.0

   # Initialize counters for total and alternate alleles
   total_alleles = 0
   alt_alleles = 0

   # Iterate over each genotype in the list
   for genotype in genotypes:
       # Check if the genotype is valid
       if genotype not in ['0/0', '0/1', '1/1', './.']:
           raise ValueError(f"Invalid genotype: {genotype}")

       # Split the genotype into alleles
       alleles = genotype.split('/')

       # Check if the genotype is missing
       if alleles[0] == '.' or alleles[1] == '.':
           continue

       # Increment the total and alternate allele counters
       total_alleles += 2
       if alleles[0] != alleles[1]:
           alt_alleles += 2

   # Calculate the alternate allele frequency
   if total_alleles == 0:
       return 0.0
   else:
       return round(alt_alleles / total_alleles, 3)

# Check if the lengths of the sequences are equal
   if len(aligned_a) != len(aligned_b):
       raise ValueError("Sequences must be of equal length")

   # Initialize counters for identical and total non-gap columns
   identical = 0
   total = 0

   # Iterate over the characters in the sequences
   for a, b in zip(aligned_a, aligned_b):
       # Check if the characters are not gaps
       if a != '-' and b != '-':
           # Check if the characters are identical
           if a == b:
               identical += 1
           # Increment the total counter
           total += 1

   # Check if there are any non-gap columns
   if total == 0:
       return 0.0
   else:
       # Calculate the percent identity
       return round((identical / total) * 100, 2)
